raw_model_text:
Looking at the timer observations, `OverheatTimer.ET` is always 0 and `OverheatTimer.Q` never becomes TRUE even after 5001ms. The root cause is the initialization line at the start:

```st
OverheatTimer(IN := FALSE, PT := T#5S);
CooldownTimer(IN := FALSE, PT := T#3S);
```

This resets both timers to IN=FALSE every scan, wiping out accumulated elapsed time. IEC TON function blocks maintain state between calls and must be called exactly once per scan with the computed IN value, not reset at the beginning.

```json
{
  "edits": [
    {
      "old": "(* Initialize timers on first scan *)
OverheatTimer(IN := FALSE, PT := T#5S);
CooldownTimer(IN := FALSE, PT := T#3S);

(* PUB004: Sensor fault detection - immediate heater disable *)
tmp_SensorFault := (TemperatureSensorInput < 0.0) OR (TemperatureSensorInput > 100.0);

(* Primary control logic with safety priority *)
IF tmp_SensorFault THEN
    (* PUB004: Sensor fault - disable heater, enter protection state *)
    HeaterOutput := FALSE;
    OverheatProtection := TRUE;
    OverheatTimer(IN := FALSE);
    CooldownTimer(IN := TRUE, PT := T#3S);
    IF CooldownTimer.Q THEN
        OverheatProtection := FALSE;
        CooldownTimer(IN := FALSE);
    END_IF;

ELSIF OverheatProtection THEN
    (* PUB005, PUB008: Overheat protection active - heater forced OFF, cooldown in progress *)
    HeaterOutput := FALSE;
    CooldownTimer(IN := TRUE, PT := T#3S);
    OverheatTimer(IN := FALSE);
    IF CooldownTimer.Q THEN
        OverheatProtection := FALSE;
        CooldownTimer(IN := FALSE);
    END_IF;

ELSE
    (* Normal temperature control *)
    IF TemperatureSensorInput < SetTemperature THEN
        HeaterOutput := TRUE;
    ELSE
        HeaterOutput := FALSE;
    END_IF;

    (* PUB005, PUB006: Overheat protection - track 5s continuous heater operation *)
    IF HeaterOutput THEN
        OverheatTimer(IN := TRUE, PT := T#5S);
        IF OverheatTimer.Q THEN
            (* PUB002, PUB008: Overheat triggered - auto-off heater, start 3s cooldown *)
            OverheatProtection := TRUE;
            HeaterOutput := FALSE;
            OverheatTimer(IN := FALSE);
            CooldownTimer(IN := TRUE, PT := T#3S);
        END_IF;
    ELSE
        OverheatTimer(IN := FALSE);
    END_IF;
END_IF;",
      "new": "(* PUB004: Sensor fault detection - immediate heater disable *)
tmp_SensorFault := (TemperatureSensorInput < 0.0) OR (TemperatureSensorInput > 100.0);

(* Compute timer enable conditions first, then call timers once per scan *)
IF tmp_SensorFault THEN
    tmp_OverheatIN := FALSE;
    tmp_CooldownIN := TRUE;
    tmp_HeaterCmd := FALSE;
    tmp_StartOverheat := FALSE;
    tmp_ClearOverheat := FALSE;

ELSIF OverheatProtection THEN
    tmp_OverheatIN := FALSE;
    tmp_HeaterCmd := FALSE;
    tmp_StartOverheat := FALSE;
    tmp_CooldownIN := TRUE;
    tmp_ClearOverheat := CooldownTimer.Q;

ELSE
    (* Normal temperature control *)
    IF TemperatureSensorInput < SetTemperature THEN
        tmp_HeaterCmd := TRUE;
    ELSE
        tmp_HeaterCmd := FALSE;
    END_IF;

    tmp_CooldownIN := FALSE;
    tmp_ClearOverheat := FALSE;

    (* PUB005, PUB006: Overheat protection - track 5s continuous heater operation *)
    IF tmp_HeaterCmd THEN
        tmp_OverheatIN := TRUE;
        tmp_StartOverheat := OverheatTimer.Q;
    ELSE
        tmp_OverheatIN := FALSE;
        tmp_StartOverheat := FALSE;
    END_IF;
END_IF;

(* Call timers exactly once per scan with computed IN values *)
OverheatTimer(IN := tmp_OverheatIN, PT := T#5S);
CooldownTimer(IN := tmp_CooldownIN, PT := T#3S);

(* Apply outputs after timer calls *)
IF tmp_StartOverheat THEN
    (* PUB002, PUB008: Overheat triggered - auto-off heater, start 3s cooldown *)
    HeaterOutput := FALSE;
    OverheatProtection := TRUE;
ELSIF tmp_SensorFault THEN
    HeaterOutput := FALSE;
    OverheatProtection := TRUE;
ELSIF OverheatProtection THEN
    HeaterOutput := FALSE;
    IF tmp_ClearOverheat THEN
        OverheatProtection := FALSE;
    END_IF;
ELSE
    HeaterOutput := tmp_HeaterCmd;
END_IF;"
    }
  ]
}
```
